const S=1.1,GC=2,GR=2;
const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
const s2=Math.SQRT1_2;
const Q={up:[-s2,0,0,s2],down:[s2,0,0,s2],left:[0,0,s2,s2],right:[0,0,-s2,s2]};
function pos(c,r){return [(c-1)*S,(r-1)*-S];}
function dist(s){return Math.abs(GC-s.c)+Math.abs(GR-s.r);}
export function initialState(){return {c:0,r:0,moves:0,hint:null,msg:'',won:false};}
export function reduce({state,event}){
if(event.type!=='action')return state;
const a=event.action;
if(state.won)return state;
if(a==='hint'){const h=state.c<GC?'right':'up';return {...state,hint:h,msg:'Hint: try '+h[0].toUpperCase()+h.slice(1)+'.'};}
const d=D[a];if(!d)return state;
const c=state.c+d[0],r=state.r+d[1];
if(c<0||c>2||r<0||r>2)return {...state,hint:null,msg:'That move would leave the board.'};
const n={...state,c,r,moves:state.moves+1,hint:null,msg:''};
if(c===GC&&r===GR)n.won=true;
return n;}
export function evaluate({state}){
const s=state||initialState();
const [x,z]=pos(s.c,s.r);
const onGoal=s.c===GC&&s.r===GR;
const nodes={tokenN:{position:[x,onGoal?0.43:0.35,z]}};
if(s.hint&&!s.won){const d=D[s.hint];nodes.hintArrow={visible:true,position:[x+d[0]*0.3,0.35,z-d[1]*0.3],quaternion:Q[s.hint]};}else nodes.hintArrow={visible:false};
const steps=dist(s);
let goal;
if(s.won)goal={status:'won',message:'You reached the goal in '+s.moves+' moves. The shortest route is 4 moves'+(s.moves===4?' - perfect!':'.')};
else goal={status:'playing',message:s.msg||'Move the token to the gold goal square.'};
return {nodes,readouts:{steps,moves:s.moves},goal};}
